import { Component } from '@angular/core';

@Component({
  selector: 'app-multiple-state',
  template: `
    <div>
      <h2>Multiple State Variables Demo</h2>
      <p>Count: {{ counter }}</p>
      <p>Name: {{ name }}</p>
      <p *ngIf="isVisible">This content is visible!</p>
      <!-- Add increment button, name input, and toggle button here -->
    </div>
  `
})
export class MultipleStateComponent {
  counter = 0;
  name = 'Angular Developer';
  isVisible = true;

  increment() {
    this.counter++;
  }

  updateName(newName: string) {
    this.name = newName;
  }

  toggleVisibility() {
    this.isVisible = !this.isVisible;
  }
}
